"""Build the public packet reference index from curated source entries."""
from pathlib import Path
import json,html,re
from urllib.parse import quote
ROOT=Path(__file__).resolve().parents[1]
roman={1:'I',2:'II',3:'III'}
def esc(s):return html.escape(str(s),quote=True)
def pages(ns):return str(ns[0]) if len(ns)==1 else '–'.join(map(str,(ns[0],ns[-1]))) if ns==list(range(ns[0],ns[-1]+1)) else ', '.join(map(str,ns))
rows=json.loads((ROOT/'tools/packet_reference_index.json').read_text())
RELEASE='https://github.com/SamanthaCooper/mvp-math-supplements/releases/download/mvp-student-packets-2026-10/'
css='''*{box-sizing:border-box}body{font:17px/1.6 system-ui;color:#172338;background:#f6f8fa;margin:0}main{max-width:1400px;margin:auto;padding:32px}h1{line-height:1.2}h2{font-size:1.2rem;margin:.4em 0}article{background:white;border:1px solid #dce5eb;border-radius:8px;padding:20px;margin:16px 0}.meta{font-size:.85rem;color:#526179;display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap}.kind{color:#145a80}a{color:#145a80}.note{font-size:.9rem;background:#fff5e8;padding:10px}input,select{font:inherit;padding:10px;border:1px solid #bcc9d5;border-radius:5px;width:100%;min-width:0}.filters{display:grid;grid-template-columns:2fr 1fr 1fr 1.4fr;gap:16px;margin-top:24px}label{display:block;font-size:.85rem;font-weight:650}.intro{background:#edf5fa;padding:18px;border-left:4px solid #145a80}article[hidden]{display:none}.muted{color:#526179;font-size:.88rem}@media(max-width:800px){main{padding:16px}.filters{grid-template-columns:1fr}}@media print{.filters{display:none}article{break-inside:avoid}}'''
cards=[]
for i,r in enumerate(rows):
 k=r['kind'].lower();cats=[v for text,v in [('definition','definition'),('worked example','worked'),('worked illustration','illustration'),('reference','reference')] if text in k]
 src=RELEASE+quote(Path(r['file']).name)+'#page='+str(r['pdf_pages'][0]);c=r['course']
 cards.append(f'''<article id="entry-{i+1}" data-course="{c}" data-module="{r['module']}" data-kind="{' '.join(cats)}"><div class="meta"><div>Math {roman[c]} · Module {r['module']} · Section {esc(r['section'])} · {esc(r['part'])}</div><span class="kind">{esc(r['kind'])}</span></div><h2>{esc(r['title'])}</h2><p>{esc(r['description'])}</p><a href="{esc(src)}">Open packet: printed p. {pages(r['printed_pages'])} · PDF page {pages(r['pdf_pages'])}</a>'''+('<p class="note">Source note: '+esc(r['note'])+'</p>' if r.get('note') else '')+'</article>')
header='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MVP packet definitions and worked examples</title><style>'''+css+'''</style></head><body><main><p><a href="index.html">← Home</a></p><h1>Definitions and worked examples in the MVP packets</h1><div class="intro"><strong>Secondary Math I, II, and III · Modules 1–9</strong><p>Find explanations already printed in your MVP packet. Entries identify definitions, completed worked examples, supplied worked illustrations, and short reference reminders. Student exercises, matching activities, and unfinished examples are excluded.</p><p>Listed source pages were visually checked. Entries point to supplied definitions, reference explanations, or completed examples—not tasks that ask students to supply or match them. This is a curated index, rather than a list of every exercise or every use of a term.</p></div><p class="muted">Updated October 13, 2026 · Links open the original student packets stored as GitHub release attachments. Your browser may download the PDF; if so, open it and go to the listed PDF page.</p><p class="muted">Source materials by <a href="honors-packets.html">Mathematics Vision Project</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Packet PDFs are unchanged; this independent index adds descriptions and references. Not affiliated with or endorsed by MVP.</p><div class="filters"><div><label for="search">Search topics</label><input id="search" placeholder="For example, polynomial division or similarity"></div><div><label for="course">Course</label><select id="course"><option value="all">All courses</option><option value="1">Math I</option><option value="2">Math II</option><option value="3">Math III</option></select></div><div><label for="module">Module</label><select id="module"><option value="all">All modules</option>'''+''.join(f'<option value="{i}">Module {i}</option>' for i in range(1,10))+'''</select></div><div><label for="kind">Type of material</label><select id="kind"><option value="all">All types</option><option value="definition">Definitions</option><option value="worked">Worked examples</option><option value="illustration">Worked illustrations</option><option value="reference">Reference reminders</option></select></div></div><p id="count" aria-live="polite"></p><p id="empty" hidden>No matches. Try a different topic or clear a filter.</p>'''
script='''<script>const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),course=document.querySelector('#course'),moduleSelect=document.querySelector('#module'),kind=document.querySelector('#kind');function filter(){const q=search.value.toLowerCase().trim(),c=course.value,m=moduleSelect.value,k=kind.value;for(const x of cards)x.hidden=!(x.textContent.toLowerCase().includes(q)&&(c==='all'||x.dataset.course===c)&&(m==='all'||x.dataset.module===m)&&(k==='all'||x.dataset.kind.split(' ').includes(k)));const n=cards.filter(x=>!x.hidden).length;document.querySelector('#count').textContent=n+(n===1?' entry':' entries');document.querySelector('#empty').hidden=n!==0;}for(const el of [search,course,moduleSelect,kind])el.addEventListener(el===search?'input':'change',filter);const initialCourse=new URLSearchParams(location.search).get('course');if(['1','2','3'].includes(initialCourse))course.value=initialCourse;filter();</script></main></body></html>'''
page=header+''.join(cards)+script
(ROOT/'packet-reference-index.html').write_text(page)
print(f'Built public index with {len(rows)} entries.')
